'use client';

import {CopyMode, type CopyModeProps} from '@/components/quartz/ui/input/copy';
import {NumberMode, autoStep, type NumberModeProps} from '@/components/quartz/ui/input/number';
import {OtpMode, type OtpModeProps} from '@/components/quartz/ui/input/otp';
import {InputAction, InputControl, InputPrefix, InputRoot, InputSuffix, splitBox, type BoxProps, type InputRootProps, type NativeProps, type StringValue} from '@/components/quartz/ui/input/parts';
import {PasswordMode, generatePassword, type PasswordModeProps} from '@/components/quartz/ui/input/password';
import {SearchMode, type SearchModeProps} from '@/components/quartz/ui/input/search';
import {SecretMode, maskSecret, type SecretModeProps} from '@/components/quartz/ui/input/secret';

// Quartz's input: one line of text, on Base UI's Input, NumberField and OTPField. Every
// mode sits in one field box (fieldBoxVariants), so they share a height, a hover edge, a fail edge and an
// ink focus edge, and an icon, unit or button in the prefix or suffix slot is inside the edge and a click on
// it focuses the text (trap/field-affix-focus).
//
// Modes (was Input group, Password input, Secret input, Copy input, Search field, Number field, Input OTP
// and Secret reveal):
//   text      any native type, with prefix and suffix slots
//   password  masked, a reveal toggle, and an optional generator for new passwords
//   secret    an API key or token in mono, masked until revealed. Read-only, it keeps its prefix and last
//             four characters visible so keys tell apart, and copies the real value while hidden
//   copy      a read-only value with Copy in the suffix; a click selects all of it
//   search    a magnifier, a clear button once there is a query, a shortcut hint while empty
//   number    Base UI NumberField: role spinbutton, steppers, a unit, limits that clamp
//   otp       one slot per character; paste fills every slot
//
// The considered detail: with step="auto", a number steps by its second significant digit, so 40 moves
// by 1, 250 by 10 and 1,200 by 100. Each step is reversible across a power of ten (1,000 down is 990,
// 990 up is 1,000), and the field shows the step it will take while focused.
//
// An editable secret that is revealed turns its edge to the key line (data-kind="key"), so a visible secret is
// obvious from across the room.
//
// Each mode lives in its own file under input/ (parts.tsx holds the box and what the modes share); this file
// picks the mode and is the one import.

type TextModeProps = BoxProps & NativeProps & StringValue & {
  mode?: 'text';
  /** Any native text type: text, email, url, tel, file. */
  type?: string;
};

type InputProps = TextModeProps | PasswordModeProps | SecretModeProps | CopyModeProps | SearchModeProps | NumberModeProps | OtpModeProps;
type InputMode = NonNullable<InputProps['mode']>;

// ---------- Input ----------

function Input(props: InputProps) {
  switch (props.mode) {
    case 'password': return <PasswordMode {...props}/>;
    case 'secret': return <SecretMode {...props}/>;
    case 'copy': return <CopyMode {...props}/>;
    case 'search': return <SearchMode {...props}/>;
    case 'number': return <NumberMode {...props}/>;
    case 'otp': return <OtpMode {...props}/>;
    default: return <TextMode {...props}/>;
  }
}

function TextMode({mode: _mode, size = 'default', prefix, suffix, className, controlClassName, disabled, readOnly, type = 'text', ...all}: TextModeProps) {
  const {box, rest} = splitBox(all);
  return <InputRoot size={size} disabled={disabled} readOnly={readOnly} invalid={rest['aria-invalid'] === true || rest['aria-invalid'] === 'true'} className={className} data-mode="text" {...box}>
    {prefix !== undefined && <InputPrefix>{prefix}</InputPrefix>}
    <InputControl type={type} disabled={disabled} readOnly={readOnly} className={controlClassName} {...rest}/>
    {suffix !== undefined && <InputSuffix>{suffix}</InputSuffix>}
  </InputRoot>;
}

export {
  Input,
  InputAction,
  InputControl,
  InputPrefix,
  InputRoot,
  InputSuffix,
  autoStep,
  generatePassword,
  maskSecret,
  type InputMode,
  type InputProps,
  type InputRootProps,
  type SearchModeProps,
};

'use client';

import {createContext, useContext, useState, type ComponentProps, type PointerEvent, type ReactNode, type Ref} from 'react';
import {Input as InputPrimitive} from '@base-ui/react/input';
import {Button, type ButtonProps} from '@/components/quartz/ui/button';
import {fieldBoxVariants, useFieldDisabled, type ControlSize} from '@/components/quartz/ui/field';
import {cn, mergeClass} from '@/lib/quartz/utils';

// The field box every Input mode sits in, and what the modes share: the size context, the disabled
// rule, the value hook and the props each mode takes for its box.

const SizeContext = createContext<ControlSize>('default');

/** The control's own disabled prop, or a disabled Field or FieldSet around it. Buttons and slots read this too. */
function useOff(disabled?: boolean) {
  const inField = useFieldDisabled();
  return !!disabled || inField;
}

// ---------- parts ----------

type InputRootProps = ComponentProps<'div'> & {
  size?: ControlSize;
  disabled?: boolean;
  readOnly?: boolean;
  invalid?: boolean;
};

/**
 * The field box. A press on the box or on a slot that is not a button focuses the control, so the whole
 * box is the hit area.
 */
function InputRoot({size = 'default', disabled: disabledProp, readOnly, invalid, className, onPointerDown, children, ...props}: InputRootProps) {
  const disabled = useOff(disabledProp);
  const down = (e: PointerEvent<HTMLDivElement>) => {
    onPointerDown?.(e);
    const target = e.target as HTMLElement;
    if (target.closest('button, a, input, textarea, [role=button]')) return;
    const control = e.currentTarget.querySelector<HTMLElement>('[data-control]');
    if (!control || disabled) return;
    e.preventDefault();
    control.focus();
  };
  return <SizeContext.Provider value={size}>
    <div
      data-slot="input"
      data-size={size}
      data-disabled={disabled || undefined}
      data-readonly={readOnly || undefined}
      data-status={invalid ? 'fail' : undefined}
      onPointerDown={down}
      className={cn(fieldBoxVariants({size}), 'cursor-text data-readonly:cursor-default', className)}
      {...props}
    >{children}</div>
  </SizeContext.Provider>;
}

/** Quiet content before the text: an icon, "https://", a currency sign. */
function InputPrefix({className, ...props}: ComponentProps<'span'>) {
  return <span
    data-slot="input-prefix"
    className={cn(
      'flex shrink-0 items-center gap-2 ps-3 type-label pointer-coarse:text-base text-text-3 select-none group-data-[size=sm]/field-box:ps-2 group-data-[size=lg]/field-box:ps-4 has-[button]:ps-1 group-data-[size=sm]/field-box:has-[button]:ps-1 group-data-[size=lg]/field-box:has-[button]:ps-1',
      '[&_svg]:text-text-2 group-data-disabled/field-box:text-text-disabled group-has-[[data-control]:disabled]/field-box:text-text-disabled',
      // Text sets its own order, so "https://" or ".helpdesk.example" read right on a right-to-left page.
      '[unicode-bidi:plaintext]',
      className,
    )}
    {...props}
  />;
}

/** Content after the text: a unit, a shortcut hint, or InputAction buttons. */
function InputSuffix({className, ...props}: ComponentProps<'span'>) {
  return <span
    data-slot="input-suffix"
    className={cn(
      'flex shrink-0 items-center gap-0.5 pe-3 type-label pointer-coarse:text-base text-text-3 select-none group-data-[size=sm]/field-box:pe-2 group-data-[size=lg]/field-box:pe-4 has-[button]:pe-1 group-data-[size=sm]/field-box:has-[button]:pe-1 group-data-[size=lg]/field-box:has-[button]:pe-1',
      '[&_svg]:text-text-2 group-data-disabled/field-box:text-text-disabled group-has-[[data-control]:disabled]/field-box:text-text-disabled',
      // Text sets its own order, so "https://" or ".helpdesk.example" read right on a right-to-left page.
      '[unicode-bidi:plaintext]',
      className,
    )}
    {...props}
  />;
}

/** The bare text control inside the box. The box draws its fill and its edge. */
function InputControl({className, ...props}: InputPrimitive.Props) {
  return <InputPrimitive
    data-slot="input-control"
    data-control=""
    className={mergeClass([
      'h-full w-full min-w-0 flex-1 bg-transparent px-3 text-inherit placeholder:text-text-3',
      'group-data-[size=sm]/field-box:px-2 group-data-[size=lg]/field-box:px-4',
      'group-has-[[data-slot=input-prefix]]/field-box:ps-2 group-has-[[data-slot=input-suffix]]/field-box:pe-2',
      'disabled:cursor-not-allowed disabled:placeholder:text-text-disabled read-only:cursor-default',
      'file:me-3 file:h-6 file:cursor-pointer file:rounded-inner file:border-0 file:bg-pressed file:px-2 file:type-label-sm file:text-text-1',
    ], className)}
    {...props}
  />;
}

/**
 * The size of a button inside the box. It leaves 4px on every side (24px in the 32px box, 20px in the 28px box,
 * 36px in the 44px box), and the corner is the inner one, since the button is a thing inside a control.
 */
function actionClass(box: ControlSize, icon = true) {
  if (icon) return cn('rounded-inner', box === 'sm' ? 'size-5' : box === 'lg' ? 'size-9' : 'size-6');
  return cn('rounded-inner', box === 'sm' ? 'h-5 px-2 type-label-sm' : box === 'lg' ? 'h-9' : 'h-6 px-2');
}

/**
 * An icon button that is not a Button, inside a field box (the combobox's chevron and clear, the time field's clock). The same
 * 4px of room and inner corner as actionClass, with the hover wash and the 44px touch target a coarse pointer gets. Pass the
 * box when the size is a prop; leave it out when the field-box group carries data-size.
 */
function fieldActionClass(box?: ControlSize) {
  return cn(
    'relative flex shrink-0 items-center justify-center rounded-inner text-text-2 touch-target',
    box === undefined ? 'size-6 group-data-[size=sm]/field-box:size-5 group-data-[size=lg]/field-box:size-9' : box === 'sm' ? 'size-5' : box === 'lg' ? 'size-9' : 'size-6',
    'transition-colors duration-(--dur-fast) ease-(--ease-step) motion-reduce:transition-none',
    'hover:not-data-disabled:bg-hover hover:not-data-disabled:text-text-1 data-disabled:text-text-disabled',
  );
}

/** A ghost button sized to sit inside the box: reveal, clear, generate, a unit switch. Icon-only needs aria-label. */
function InputAction({className, size, variant = 'ghost', ...props}: Omit<ButtonProps, 'size'> & {size?: 'icon' | 'text'}) {
  const box = useContext(SizeContext);
  const icon = (size ?? 'icon') === 'icon';
  return <Button
    data-slot="input-action"
    variant={variant}
    size={icon ? 'icon-sm' : 'sm'}
    className={mergeClass([
      variant === 'ghost' && 'bg-transparent hover:not-data-disabled:bg-hover',
      actionClass(box, icon),
    ], className)}
    {...props}
  />;
}

// ---------- shared value hook ----------

function useControllable<T>(value: T | undefined, defaultValue: T, onChange?: (next: T) => void) {
  const [inner, setInner] = useState(defaultValue);
  const current = value !== undefined ? value : inner;
  const set = (next: T) => { if (value === undefined) setInner(next); onChange?.(next); };
  return [current, set] as const;
}

// ---------- props ----------

type BoxProps = {
  /** 28, 32 or 44px tall. Match the buttons beside it. */
  size?: ControlSize;
  /** Inside the box, before the text. */
  prefix?: ReactNode;
  /** Inside the box, after the text. */
  suffix?: ReactNode;
  /** Classes for the box: width and placement. */
  className?: string;
  /** Classes for the text control, for type changes such as mono. */
  controlClassName?: string;
  ref?: Ref<HTMLInputElement>;
};

type NativeProps = Omit<InputPrimitive.Props, 'size' | 'prefix' | 'className' | 'type' | 'value' | 'defaultValue' | 'onValueChange' | 'ref'>;
type StringValue = {value?: string; defaultValue?: string; onValueChange?: (value: string) => void};

/** Splits box props (forced states, data-kind) from the props meant for the text control. */
function splitBox<T extends Record<string, unknown>>(props: T) {
  const box: Record<string, unknown> = {};
  const rest: Record<string, unknown> = {};
  for (const [k, v] of Object.entries(props)) (k.startsWith('data-force-') || k === 'data-kind' || k === 'style' ? box : rest)[k] = v;
  return {box, rest: rest as T};
}

export {
  InputAction, InputControl, InputPrefix, InputRoot, InputSuffix, SizeContext, actionClass, fieldActionClass, splitBox, useControllable, useOff,
  type BoxProps, type InputRootProps, type NativeProps, type StringValue,
};

'use client';

import {useState, type ChangeEvent} from 'react';
import {Icon, Renew, View, ViewOff} from '@/components/quartz/icon';
import {cn} from '@/lib/quartz/utils';
import {InputAction, InputControl, InputPrefix, InputRoot, InputSuffix, splitBox, useControllable, useOff, type BoxProps, type NativeProps, type StringValue} from '@/components/quartz/ui/input/parts';

type PasswordModeProps = BoxProps & NativeProps & StringValue & {
  mode: 'password';
  /** Adds Generate. Use for new passwords only, never sign-in. Pass a function to use your own generator. */
  generate?: boolean | (() => string);
  defaultRevealed?: boolean;
};

const ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789-_!@#%';

/** A random password from the crypto RNG, without look-alike characters (0, O, 1, l, I). */
function generatePassword(length = 24) {
  const bytes = crypto.getRandomValues(new Uint32Array(length));
  return Array.from(bytes, b => ALPHABET[b % ALPHABET.length]).join('');
}

function PasswordMode({mode: _mode, size = 'default', prefix, suffix: _suffix, className, controlClassName, value, defaultValue = '', onValueChange, onChange, generate, defaultRevealed = false, disabled: disabledProp, autoComplete, ...all}: PasswordModeProps) {
  const disabled = useOff(disabledProp);
  const {box, rest} = splitBox(all);
  const [current, set] = useControllable(value, defaultValue, onValueChange);
  const [revealed, setRevealed] = useState(defaultRevealed);
  const make = typeof generate === 'function' ? generate : () => generatePassword();
  return <InputRoot size={size} disabled={disabled} invalid={rest['aria-invalid'] === true || rest['aria-invalid'] === 'true'} className={className} data-mode="password" {...box}>
    {prefix !== undefined && <InputPrefix>{prefix}</InputPrefix>}
    <InputControl
      type={revealed ? 'text' : 'password'}
      value={current}
      onChange={(e: ChangeEvent<HTMLInputElement>) => { set(e.target.value); onChange?.(e as never); }}
      disabled={disabled}
      autoComplete={autoComplete ?? (generate ? 'new-password' : 'current-password')}
      autoCapitalize="off"
      spellCheck={false}
      className={cn(revealed && 'type-code pointer-coarse:type-code-touch', controlClassName)}
      {...rest}
    />
    <InputSuffix>
      {generate && <InputAction size="text" disabled={disabled} onClick={() => { set(make()); setRevealed(true); }}>
        <Icon icon={Renew} size={16}/>Generate
      </InputAction>}
      <InputAction
        disabled={disabled}
        aria-pressed={revealed}
        aria-label={revealed ? 'Hide password' : 'Show password'}
        onClick={() => setRevealed(r => !r)}
      ><Icon icon={revealed ? ViewOff : View} size={16}/></InputAction>
    </InputSuffix>
  </InputRoot>;
}

export {PasswordMode, generatePassword, type PasswordModeProps};

'use client';

import {useEffect, useId, useMemo, useRef, useState, type ChangeEvent, type FocusEvent} from 'react';
import {Icon, View, ViewOff} from '@/components/quartz/icon';
import {cn, mergeRefs} from '@/lib/quartz/utils';
import {EMPTY_VALUE} from '@/lib/quartz/format';
import {CopyButton} from '@/components/quartz/ui/copy-button';
import {InputAction, InputControl, InputPrefix, InputRoot, InputSuffix, actionClass, splitBox, useControllable, useOff, type BoxProps, type NativeProps, type StringValue} from '@/components/quartz/ui/input/parts';

type SecretModeProps = BoxProps & NativeProps & StringValue & {
  mode: 'secret';
  /** What the secret is, for button names: "key" gives "Show key". */
  noun?: string;
  revealed?: boolean;
  defaultRevealed?: boolean;
  onRevealedChange?: (revealed: boolean) => void;
  /** Mask again when focus leaves the field. */
  hideOnBlur?: boolean;
  /** Mask again this many ms after revealing. 0 keeps it shown. Default 30000 read-only, 0 editable. */
  hideAfter?: number;
  /** The server kept only the tail: no reveal, no copy. Implies readOnly. */
  redacted?: boolean;
  /** A Copy button in the suffix. Default true when read-only. */
  copyable?: boolean;
  /** Runs after the value is copied, for a next step such as "now paste it in your site". */
  onCopy?: () => void;
  /** Visible characters at the end of a read-only mask. */
  tail?: number;
};

/** The visible prefix of a key: everything up to and including the last _ or - in the first 12 characters. */
function keyPrefixLength(value: string) {
  const head = value.slice(0, 12);
  return Math.max(head.lastIndexOf('_'), head.lastIndexOf('-')) + 1;
}

/**
 * "sk_demo_••••••••••••••••i0p0" style mask: the prefix and the tail stay, with one dot per hidden character, so the
 * masked key has the revealed key's exact length and a key pasted ten characters short looks short. Only when the
 * field cannot hold the whole length (capacity, in characters) do the dots shrink to fit, never below 4; then the
 * prefix drops. The tail is what tells two keys apart, so it is never cut. A caller that shows a shrunk mask says the
 * real length in words.
 */
function maskSecret(value: string, tail = 4, capacity = Infinity) {
  const prefix = keyPrefixLength(value);
  if (value.length <= prefix + tail) return '•'.repeat(value.length);
  const hidden = value.length - prefix - tail;
  const floor = Math.min(4, hidden);
  let head = prefix;
  let dots = hidden;
  if (head + dots + tail > capacity) dots = Math.max(floor, capacity - head - tail);
  if (head + dots + tail > capacity) { head = 0; dots = Math.max(floor, Math.min(hidden + prefix, capacity - tail)); }
  return value.slice(0, head) + '•'.repeat(dots) + value.slice(-tail);
}

/** How many characters of the control's own font fit on its line, or Infinity until it is measured. */
function useCapacity(ref: {current: HTMLInputElement | null}) {
  const [capacity, setCapacity] = useState(Infinity);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const measure = () => {
      const cs = getComputedStyle(el);
      const ctx = document.createElement('canvas').getContext('2d');
      if (!ctx) return;
      ctx.font = `${cs.fontStyle} ${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`;
      const char = ctx.measureText('0').width;
      const room = el.clientWidth - parseFloat(cs.paddingLeft) - parseFloat(cs.paddingRight);
      if (char > 0 && room > 0) setCapacity(Math.floor(room / char));
    };
    measure();
    const observer = new ResizeObserver(measure);
    observer.observe(el);
    return () => observer.disconnect();
  }, [ref]);
  return capacity;
}

function SecretMode({
  mode: _mode, size = 'default', prefix, suffix: _suffix, className, controlClassName, value, defaultValue = '', onValueChange, onChange,
  noun = 'value', revealed: revealedProp, defaultRevealed = false, onRevealedChange, hideOnBlur = false, hideAfter, redacted = false,
  copyable, onCopy, tail = 4, disabled: disabledProp, readOnly: readOnlyProp, onBlur, ref, ...all
}: SecretModeProps) {
  const disabled = useOff(disabledProp);
  const {box, rest} = splitBox(all);
  const readOnly = readOnlyProp || redacted;
  const [current, set] = useControllable(value, defaultValue, onValueChange);
  const [revealed, setRevealed] = useControllable(revealedProp, defaultRevealed, onRevealedChange);
  const shown = revealed && !redacted;
  const after = hideAfter ?? (readOnly ? 30_000 : 0);
  const describe = useId();

  useEffect(() => {
    if (!shown || !after) return;
    const t = setTimeout(() => setRevealed(false), after);
    return () => clearTimeout(t);
  }, [shown, after]); // eslint-disable-line react-hooks/exhaustive-deps

  const control = useRef<HTMLInputElement | null>(null);
  const capacity = useCapacity(control);
  const setControl = useMemo(() => mergeRefs<HTMLInputElement>(control, ref), [ref]);
  const display = readOnly && !shown ? maskSecret(current, tail, capacity) : current;
  // The field could not hold one dot per character, so the real length goes into the description.
  const shrunk = display.length < current.length;
  const canCopy = (copyable ?? readOnly) && !redacted;
  return <InputRoot
    size={size}
    disabled={disabled}
    readOnly={readOnly}
    invalid={rest['aria-invalid'] === true || rest['aria-invalid'] === 'true'}
    // A visible secret is obvious across the room through the key's line on the edge, never a fill.
    className={cn('data-revealed:not-data-readonly:[--frame-color:var(--accent-line)]', className)}
    data-mode="secret"
    data-kind={shown ? 'key' : undefined}
    data-revealed={shown || undefined}
    data-redacted={redacted || undefined}
    onBlur={(e: FocusEvent<HTMLDivElement>) => { if (hideOnBlur && shown && !e.currentTarget.contains(e.relatedTarget)) setRevealed(false); }}
    {...box}
  >
    {prefix !== undefined && <InputPrefix>{prefix}</InputPrefix>}
    <InputControl
      // The caller's props first: the type, value and password-manager opt-outs below are what keep the secret masked.
      {...rest}
      ref={setControl}
      type={readOnly || shown ? 'text' : 'password'}
      value={display}
      onChange={(e: ChangeEvent<HTMLInputElement>) => { set(e.target.value); onChange?.(e as never); }}
      onBlur={onBlur}
      disabled={disabled}
      readOnly={readOnly}
      autoComplete="off"
      autoCapitalize="off"
      spellCheck={false}
      data-1p-ignore=""
      data-lpignore="true"
      data-bwignore=""
      aria-describedby={cn(rest['aria-describedby'] as string | undefined, readOnly && !shown && current && describe) || undefined}
      placeholder={readOnly ? EMPTY_VALUE : rest.placeholder as string | undefined}
      className={cn('type-code pointer-coarse:type-code-touch', redacted && 'text-text-2', controlClassName)}
    />
    {readOnly && !shown && current && <span id={describe} className="sr-only">{`Hidden, ending in ${current.slice(-tail)}${shrunk ? `, ${current.length} characters` : ''}`}</span>}
    {(!redacted || canCopy) && !(readOnly && !current) && <InputSuffix>
      {!redacted && <InputAction
        disabled={disabled}
        aria-pressed={shown}
        aria-label={`${shown ? 'Hide' : 'Show'} ${noun}`}
        onClick={() => setRevealed(!shown)}
      ><Icon icon={shown ? ViewOff : View} size={16}/></InputAction>}
      {canCopy && <CopyButton value={current} label={noun} disabled={disabled} onCopy={onCopy} className={actionClass(size)}/>}
    </InputSuffix>}
  </InputRoot>;
}

export {SecretMode, maskSecret, type SecretModeProps};

'use client';

import type {FocusEvent} from 'react';
import {cn} from '@/lib/quartz/utils';
import {EMPTY_VALUE} from '@/lib/quartz/format';
import {CopyButton} from '@/components/quartz/ui/copy-button';
import {InputControl, InputPrefix, InputRoot, InputSuffix, actionClass, splitBox, useOff, type BoxProps, type NativeProps} from '@/components/quartz/ui/input/parts';

type CopyModeProps = BoxProps & Omit<NativeProps, 'onCopy'> & {
  mode: 'copy';
  value: string;
  /** The button's label, a verb: "Copy", "Copy URL". */
  copyLabel?: string;
  onCopy?: (value: string) => void;
  /** Mono for IDs, keys, URLs and commands. Default true. */
  mono?: boolean;
  /** Shows a state of the Copy button without a click, for the docs states. */
  forceCopyState?: 'copied' | 'failed';
};

function CopyMode({mode: _mode, size = 'default', prefix, suffix: _suffix, className, controlClassName, value, copyLabel = 'Copy', onCopy, mono = true, forceCopyState, disabled: disabledProp, ...all}: CopyModeProps) {
  const disabled = useOff(disabledProp);
  const {box, rest} = splitBox(all);
  return <InputRoot size={size} disabled={disabled} readOnly className={className} data-mode="copy" {...box}>
    {prefix !== undefined && <InputPrefix>{prefix}</InputPrefix>}
    <InputControl
      readOnly
      value={value}
      disabled={disabled}
      placeholder={EMPTY_VALUE}
      onFocus={(e: FocusEvent<HTMLInputElement>) => e.currentTarget.select()}
      className={cn('truncate', mono && 'type-code pointer-coarse:type-code-touch', controlClassName)}
      {...rest}
    />
    <InputSuffix>
      <CopyButton
        value={value}
        label={copyLabel === 'Copy' ? undefined : copyLabel.replace(/^Copy\s*/, '')}
        showLabel={size !== 'sm'}
        onCopy={onCopy as never}
        forceState={forceCopyState}
        disabled={disabled || !value}
        className={cn('bg-transparent hover:not-data-disabled:bg-hover', actionClass(size, size === 'sm'))}
      />
    </InputSuffix>
  </InputRoot>;
}

export {CopyMode, type CopyModeProps};

'use client';

import {useEffect, useMemo, useRef, type ChangeEvent, type KeyboardEvent} from 'react';
import {Icon, CircleDash, Search, Close} from '@/components/quartz/icon';
import {cn, mergeRefs} from '@/lib/quartz/utils';
import {Kbd} from '@/components/quartz/ui/kbd';
import {InputAction, InputControl, InputPrefix, InputRoot, InputSuffix, splitBox, useControllable, useOff, type BoxProps, type NativeProps, type StringValue} from '@/components/quartz/ui/input/parts';

type SearchModeProps = BoxProps & NativeProps & StringValue & {
  mode: 'search';
  /** One key that focuses the field from anywhere outside another text field, dialog or menu, shown while empty. Usually "/". When several fields on a page claim the same key, the first in document order owns it. */
  shortcut?: string;
  /** false shows the hint without claiming the key, for a second field that only needs to look the same. */
  shortcutOwner?: boolean;
  clearLabel?: string;
  /** A search is running: the magnifier turns into a spinner. */
  pending?: boolean;
};

const isEditable = (el: EventTarget | null) =>
  el instanceof HTMLElement && (el.isContentEditable || ['INPUT', 'TEXTAREA', 'SELECT'].includes(el.tagName));

// One key, one owner. Every search field with a shortcut registers here, and a single window listener hands
// the key to the first enabled field in document order, so a page with several fields never has two of them
// fight over "/" (and never jumps to the last one mounted).
type ShortcutEntry = {el: () => HTMLInputElement | null; key: string; disabled: boolean};
const shortcuts = new Set<ShortcutEntry>();
function onShortcutKey(e: globalThis.KeyboardEvent) {
  if (e.defaultPrevented || e.metaKey || e.ctrlKey || e.altKey || e.isComposing || isEditable(e.target)) return;
  // An open listbox or a combobox's popup owns every printable key for its typeahead, "/" included.
  if (e.target instanceof Element && e.target.closest('[role=listbox], [role=option], [role=combobox], [role=tree], [role=grid]')) return;
  // Inside an open dialog or menu the key stays there; it never pulls focus to a field behind the overlay.
  const layer = e.target instanceof Element ? e.target.closest('[role=dialog], [role=alertdialog], [role=menu]') : null;
  const owners = [...shortcuts]
    .filter(entry => entry.key === e.key && !entry.disabled && entry.el()?.isConnected && (!layer || layer.contains(entry.el())))
    .map(entry => entry.el()!)
    .sort((a, b) => (a.compareDocumentPosition(b) & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1));
  if (!owners.length) return;
  e.preventDefault();
  owners[0].focus();
}
function claimShortcut(entry: ShortcutEntry) {
  if (!shortcuts.size) window.addEventListener('keydown', onShortcutKey);
  shortcuts.add(entry);
  return () => {
    shortcuts.delete(entry);
    if (!shortcuts.size) window.removeEventListener('keydown', onShortcutKey);
  };
}

function SearchMode({mode: _mode, size = 'default', prefix: _prefix, suffix: _suffix, className, controlClassName, value, defaultValue = '', onValueChange, onChange, shortcut, shortcutOwner = true, clearLabel = 'Clear search', pending, disabled: disabledProp, onKeyDown, ref, ...all}: SearchModeProps) {
  const disabled = useOff(disabledProp);
  const {box, rest} = splitBox(all);
  const [current, set] = useControllable(value, defaultValue, onValueChange);
  const inner = useRef<HTMLInputElement | null>(null);

  useEffect(() => {
    if (!shortcut || !shortcutOwner || disabled) return;
    return claimShortcut({el: () => inner.current, key: shortcut, disabled: false});
  }, [shortcut, shortcutOwner, disabled]);

  const setRef = useMemo(() => mergeRefs<HTMLInputElement>(inner, ref), [ref]);

  return <InputRoot size={size} disabled={disabled} invalid={rest['aria-invalid'] === true || rest['aria-invalid'] === 'true'} className={className} data-mode="search" data-pending={pending || undefined} {...box}>
    <InputPrefix>{pending
      ? <Icon icon={CircleDash} size={16} className="animate-spin motion-reduce:animate-none"/>
      : <Icon icon={Search} size={16}/>}</InputPrefix>
    <InputControl
      ref={setRef}
      type="search"
      value={current}
      disabled={disabled}
      onChange={(e: ChangeEvent<HTMLInputElement>) => { set(e.target.value); onChange?.(e as never); }}
      onKeyDown={(e: KeyboardEvent<HTMLInputElement>) => {
        onKeyDown?.(e as never);
        if (e.key !== 'Escape' || e.nativeEvent.isComposing) return;
        if (current) { e.preventDefault(); e.stopPropagation(); set(''); }
        else inner.current?.blur();
      }}
      autoComplete="off"
      spellCheck={false}
      enterKeyHint="search"
      className={cn('[&::-webkit-search-cancel-button]:appearance-none', controlClassName)}
      {...rest}
    />
    {current && !disabled
      ? <InputSuffix>
          <InputAction aria-label={clearLabel} onClick={() => { set(''); inner.current?.focus(); }}><Icon icon={Close} size={16}/></InputAction>
        </InputSuffix>
      // A touch phone has no "/" key to press, so the hint hides on a coarse pointer or a screen without hover.
      : shortcut && <InputSuffix aria-hidden className="touch:hidden">
          <Kbd>{shortcut}</Kbd>
        </InputSuffix>}
  </InputRoot>;
}

export {SearchMode, type SearchModeProps};

'use client';

import {useEffect, useMemo, useRef, useState, type CSSProperties, type KeyboardEvent, type PointerEvent, type ReactNode, type Ref} from 'react';
import {NumberField as NumberFieldPrimitive} from '@base-ui/react/number-field';
import {Icon, Subtract, Add} from '@/components/quartz/icon';
import {cn, mergeRefs} from '@/lib/quartz/utils';
import {InputPrefix, InputRoot, splitBox, useControllable, useOff, type BoxProps} from '@/components/quartz/ui/input/parts';

type NumberModeProps = Omit<BoxProps, 'ref'> & {
  mode: 'number';
  value?: number | null;
  defaultValue?: number | null;
  onValueChange?: (value: number | null) => void;
  min?: number;
  max?: number;
  /** A fixed step, or "auto" to step by the value's second significant digit. Shift and Page keys step 10x. */
  step?: number | 'auto';
  /** Text after the value: "ms", "tokens", "USD". */
  unit?: ReactNode;
  format?: Intl.NumberFormatOptions;
  /** Default en-US, so server and browser format alike. */
  locale?: string;
  name?: string;
  id?: string;
  disabled?: boolean;
  readOnly?: boolean;
  required?: boolean;
  placeholder?: string;
  'aria-label'?: string;
  'aria-describedby'?: string;
  'aria-invalid'?: boolean;
  ref?: Ref<HTMLInputElement>;
};

// ---------- number ----------

/**
 * The step for "auto": the value's second significant digit. Moving toward zero across a power of ten
 * takes the smaller step, so every step can be undone by the opposite one.
 */
function autoStep(value: number | null, direction: 1 | -1) {
  const v = value ?? 0;
  const shrinking = direction === -1 ? v > 0 : v < 0;
  const magnitude = Math.abs(v) - (shrinking ? 1e-9 : 0);
  if (magnitude < 10) return 1;
  return 10 ** (Math.floor(Math.log10(magnitude)) - 1);
}

const decimals = (n: number) => (String(n).split('.')[1] ?? '').length;

/** What the step hint says: "±100", or "−10 +100" where the two steps differ (across a power of ten). */
function stepHint(down: number, up: number, fmt: Intl.NumberFormat) {
  return down === up ? `±${fmt.format(up)}` : `−${fmt.format(down)} +${fmt.format(up)}`;
}

/** Reads the number out of text a person typed or the formatter wrote, or null. */
function readNumber(text: string, locale: string, percent: boolean) {
  const decimal = new Intl.NumberFormat(locale).formatToParts(1.1).find(p => p.type === 'decimal')?.value ?? '.';
  const cleaned = text.replace(/[\u2212\u2012-\u2014]/g, '-').split('').filter((c, i) => /\d/.test(c) || c === decimal || (c === '-' && !text.slice(0, i).replace(/\s/g, ''))).join('').replace(decimal, '.');
  const n = Number(cleaned);
  if (!cleaned || cleaned === '-' || Number.isNaN(n)) return null;
  return percent ? n / 100 : n;
}

/** Types text into an input the way a person would, so Base UI hears an input event and keeps its own text. */
function writeText(el: HTMLInputElement, text: string) {
  Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'value')?.set?.call(el, text);
  el.dispatchEvent(new Event('input', {bubbles: true}));
}

function NumberMode({
  mode: _mode, size = 'default', prefix, className, controlClassName, value, defaultValue = null, onValueChange, min, max, step = 1, unit, format,
  locale = 'en-US', name, id, disabled: disabledProp, readOnly, required, placeholder, 'aria-label': ariaLabel, 'aria-describedby': describedBy,
  'aria-invalid': ariaInvalid, ref, ...all
}: NumberModeProps) {
  const disabled = useOff(disabledProp);
  const {box} = splitBox(all as Record<string, unknown>);
  const [current, set] = useControllable<number | null>(value, defaultValue, onValueChange);
  const auto = step === 'auto';
  const stepFor = (direction: 1 | -1) => auto ? autoStep(current, direction) : step;
  const clamp = (n: number) => Math.min(max ?? Infinity, Math.max(min ?? -Infinity, n));
  const fmt = new Intl.NumberFormat(locale, format);

  // The latest value, so a held stepper compounds its steps between renders.
  const latest = useRef(current);
  latest.current = current;
  const inputEl = useRef<HTMLInputElement | null>(null);
  const setInputEl = useMemo(() => mergeRefs<HTMLInputElement>(inputEl, ref), [ref]);
  const percent = format?.style === 'percent';

  // Under 8rem the steppers go and the digits keep the room; the arrow keys still step.
  const rootRef = useRef<HTMLDivElement | null>(null);
  const [compact, setCompact] = useState(false);
  useEffect(() => {
    const el = rootRef.current;
    if (!el) return;
    const observer = new ResizeObserver(([entry]) => setCompact(entry.contentRect.width < 128));
    observer.observe(el);
    return () => observer.disconnect();
  }, []);
  const nudge = (direction: 1 | -1, multiplier = 1) => {
    if (disabled || readOnly) return false;
    // Step from what the text says. A number typed but not yet committed counts, so the shown text, the
    // value and the submitted value never part ways.
    const el = inputEl.current;
    let now = latest.current;
    if (el) {
      const shown = now === null ? '' : fmt.format(now);
      if (el.value !== shown) now = readNumber(el.value, locale, percent);
    }
    const s = (auto ? autoStep(now, direction) : step as number) * multiplier;
    const base = now ?? (direction === 1 ? (min ?? 0) - s : (max ?? 0) + s);
    const next = clamp(Number((base + direction * s).toFixed(Math.max(decimals(s), decimals(base)))));
    if (next === now) return false;
    latest.current = next;
    set(next);
    // Base UI keeps typed text until blur. Writing the step into it as typing makes the text, the value and
    // the form field one number again.
    if (el && document.activeElement === el) writeText(el, fmt.format(next));
    return true;
  };

  // Press and hold repeats: one step on press, then after 400ms a step every 60ms until release or a
  // bound. The release is heard on the window, because a stepper that reaches its bound turns disabled
  // and a disabled button gets no pointerup.
  const repeat = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const stopRepeat = () => { clearTimeout(repeat.current); repeat.current = undefined; };
  useEffect(() => stopRepeat, []);
  const hold = (direction: 1 | -1) => (e: PointerEvent<HTMLButtonElement>) => {
    if (e.button !== 0) return;
    e.preventDefault();
    const multiplier = e.shiftKey ? 10 : 1;
    stopRepeat();
    if (!nudge(direction, multiplier)) return;
    const tick = () => { repeat.current = nudge(direction, multiplier) ? setTimeout(tick, 60) : undefined; };
    repeat.current = setTimeout(tick, 400);
    window.addEventListener('pointerup', stopRepeat, {once: true});
    window.addEventListener('pointercancel', stopRepeat, {once: true});
  };

  const onKeyDown = (e: KeyboardEvent<HTMLInputElement> & {preventBaseUIHandler?: () => void}) => {
    const keys: Record<string, [1 | -1, number]> = {ArrowUp: [1, 1], ArrowDown: [-1, 1], PageUp: [1, 10], PageDown: [-1, 10]};
    const hit = keys[e.key];
    if (!hit) return;
    e.preventDefault();
    e.preventBaseUIHandler?.();
    nudge(hit[0], e.shiftKey ? hit[1] * 10 : hit[1]);
  };

  const up = stepFor(1);
  const down = stepFor(-1);
  const digits = Math.max(2, current === null ? 0 : fmt.format(current).length) + 1;
  const atMax = max !== undefined && current !== null && current >= max;
  const atMin = min !== undefined && current !== null && current <= min;
  const stepper = 'group-data-compact/field-box:hidden flex shrink-0 items-center justify-center self-stretch rounded-none text-text-2 select-none hover:not-disabled:bg-hover hover:not-disabled:text-text-1 active:not-disabled:bg-pressed disabled:cursor-not-allowed disabled:text-text-disabled';
  // Each stepper is as wide as the box is tall, so it is a square cell: 28, 32 and 44px.
  const stepperSize = size === 'sm' ? 'w-(--control-sm)' : size === 'lg' ? 'w-(--control-lg)' : 'w-(--control)';
  // The steppers are end cells, each behind a 1px row rule, so the field reads as − value +.
  const decCell = 'shadow-[inset_-1px_0_0_var(--line-row)] rtl:shadow-[inset_1px_0_0_var(--line-row)]';
  const incCell = 'rule-col';

  return <NumberFieldPrimitive.Root
    ref={rootRef}
    value={current}
    onValueChange={next => set(next)}
    min={min}
    max={max}
    step={auto ? 'any' : step}
    format={format}
    locale={locale}
    name={name}
    id={id}
    disabled={disabled}
    readOnly={readOnly}
    required={required}
    render={<InputRoot size={size} disabled={disabled} readOnly={readOnly} invalid={ariaInvalid} className={cn('gap-0 overflow-clip px-0', className)} data-mode="number" data-compact={compact || undefined} {...box}/>}
  >
    {prefix !== undefined && <InputPrefix className="ps-2">{prefix}</InputPrefix>}
    <button type="button" tabIndex={-1} data-slot="input-decrement" aria-label={`Decrease by ${fmt.format(down)}`} title={`−${fmt.format(down)}`} disabled={disabled || readOnly || atMin} onPointerDown={hold(-1)} onPointerLeave={stopRepeat} onClick={e => { if (e.detail === 0) nudge(-1, e.shiftKey ? 10 : 1); }} className={cn(stepper, stepperSize, decCell)}>
      <Icon icon={Subtract} size={16}/>
    </button>
    <span className="flex min-w-0 flex-auto items-center justify-center gap-1 self-stretch" style={{'--digits': `${digits}ch`} as CSSProperties}>
      {auto && <span
        data-slot="input-step"
        aria-hidden
        className="max-w-0 min-w-0 shrink overflow-hidden type-label-sm whitespace-nowrap text-text-3 opacity-0 transition-opacity duration-(--dur-fast) group-has-[[data-control]:focus-visible]/field-box:max-w-40 group-has-[[data-control]:focus-visible]/field-box:opacity-100 group-data-force-focus-visible/field-box:max-w-40 group-data-force-focus-visible/field-box:opacity-100"
      >{stepHint(down, up, fmt)}</span>}
      <NumberFieldPrimitive.Input
        ref={setInputEl}
        data-slot="input-control"
        data-control=""
        placeholder={placeholder}
        aria-label={ariaLabel}
        aria-describedby={describedBy}
        aria-invalid={ariaInvalid || undefined}
        role="spinbutton"
        aria-valuenow={current ?? undefined}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuetext={current !== null && unit !== undefined && typeof unit === 'string' ? `${fmt.format(current)} ${unit}` : undefined}
        onKeyDown={onKeyDown}
        className={cn(
          'h-full w-auto min-w-(--digits) flex-1 field-sizing-content bg-transparent text-center type-label data text-inherit pointer-coarse:text-base placeholder:text-text-3 disabled:cursor-not-allowed',
          unit !== undefined && 'text-end',
          controlClassName,
        )}
      />
      {unit !== undefined && <span data-slot="input-unit" aria-hidden className="min-w-0 shrink overflow-hidden type-label whitespace-nowrap text-text-3 group-has-[[data-control]:disabled]/field-box:text-text-disabled">{unit}</span>}
    </span>
    <button type="button" tabIndex={-1} data-slot="input-increment" aria-label={`Increase by ${fmt.format(up)}`} title={`+${fmt.format(up)}`} disabled={disabled || readOnly || atMax} onPointerDown={hold(1)} onPointerLeave={stopRepeat} onClick={e => { if (e.detail === 0) nudge(1, e.shiftKey ? 10 : 1); }} className={cn(stepper, stepperSize, incCell)}>
      <Icon icon={Add} size={16}/>
    </button>
  </NumberFieldPrimitive.Root>;
}

export {NumberMode, autoStep, type NumberModeProps};

'use client';

import {useId, useState} from 'react';
import {OTPField as OTPFieldPrimitive} from '@base-ui/react/otp-field';
import {cn} from '@/lib/quartz/utils';
import {splitBox, useControllable, useOff, type BoxProps} from '@/components/quartz/ui/input/parts';

type OtpModeProps = Pick<BoxProps, 'size' | 'className'> & {
  mode: 'otp';
  /** Number of slots. */
  length: number;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Fires once every slot is filled, and again for a pasted full code. */
  onComplete?: (value: string) => void;
  /** Slots per group, split by a dash. Default: two halves for 6 or 8, else one group. */
  groups?: number[];
  validationType?: OTPFieldPrimitive.Root.Props['validationType'];
  normalizeValue?: (value: string) => string;
  inputMode?: OTPFieldPrimitive.Root.Props['inputMode'];
  name?: string;
  id?: string;
  disabled?: boolean;
  autoFocus?: boolean;
  'aria-label'?: string;
  'aria-describedby'?: string;
  'aria-invalid'?: boolean;
};

// ---------- otp ----------

function OtpMode({
  mode: _mode, size = 'default', className, length, value, defaultValue = '', onValueChange, onComplete, groups, validationType = 'numeric',
  normalizeValue, inputMode, name, id, disabled: disabledProp, autoFocus, 'aria-label': ariaLabel, 'aria-describedby': describedBy, 'aria-invalid': ariaInvalid, ...all
}: OtpModeProps) {
  const disabled = useOff(disabledProp);
  // Base UI ignores aria-label on the first slot, which it names from a label element, so the name is one.
  const labelId = useId();
  const {box} = splitBox(all as Record<string, unknown>);
  const [current, set] = useControllable(value, defaultValue, onValueChange);
  const [rejected, setRejected] = useState('');
  const split = groups ?? (length >= 6 && length % 2 === 0 ? [length / 2, length / 2] : [length]);
  const starts = split.map((_, i) => split.slice(0, i).reduce((a, b) => a + b, 0));
  const slot = cn(
    'min-w-0 rounded-soft bg-page control-edge text-center data text-text-1 caret-ink outline-none forced-colors:border',
    'transition-[background-color,box-shadow,outline-color] duration-(--dur-fast) ease-(--ease-step)',
    // Each slot is its own box with its own edge. Focus turns that edge ink, with no outline around it; base.css leaves a [data-control] unringed.
    // A filled slot's edge is darker, so progress through the code reads on the edges. Invalid is the fail line.
    'focus-visible:[--frame-color:var(--border-focus)]! focus-visible:[--control-lift:var(--focus-halo)]! data-filled:not-data-invalid:[--frame-color:var(--line-control-hover)]',
    'hover:not-data-disabled:not-data-invalid:[--frame-color:var(--line-control-hover)]',
    'in-data-[status=fail]:[--frame-color:var(--fail-line)]! data-invalid:[--frame-color:var(--fail-line)]',
    'data-disabled:cursor-not-allowed data-disabled:text-text-disabled data-disabled:[--frame-color:var(--line-row)] data-disabled:[--control-lift:var(--elev-none)]',
    size === 'sm' ? 'h-(--control-sm) w-7 type-label pointer-coarse:text-base' : size === 'lg' ? 'h-(--control-lg) w-10 type-heading-sm' : 'h-(--control) w-8 type-label pointer-coarse:text-base',
  );
  return <OTPFieldPrimitive.Root
    data-slot="input"
    data-mode="otp"
    data-size={size}
    data-status={ariaInvalid ? 'fail' : undefined}
    length={length}
    value={current}
    onValueChange={v => { set(v); setRejected(''); }}
    onValueComplete={v => onComplete?.(v)}
    onValueInvalid={() => setRejected(validationType === 'numeric' ? 'Digits only' : validationType === 'alpha' ? 'Letters only' : 'Letters and digits only')}
    validationType={validationType}
    normalizeValue={normalizeValue}
    inputMode={inputMode}
    name={name}
    id={id}
    disabled={disabled}
    className={cn('flex w-fit items-center gap-2 data-disabled:cursor-not-allowed', className)}
    // A code reads left to right in every language, so its slots do too.
    dir="ltr"
    {...box}
  >
    {split.map((count, g) => <span key={g} className="contents">
      {g > 0 && <OTPFieldPrimitive.Separator data-slot="input-otp-separator" className="h-0.5 w-2 shrink-0 bg-text-3"/>}
      <span data-slot="input-otp-group" className="flex items-center gap-1">
        {Array.from({length: count}, (_, i) => {
          const index = starts[g] + i;
          return <OTPFieldPrimitive.Input
            key={index}
            data-slot="input-otp-slot"
            data-control=""
            autoFocus={autoFocus && index === 0}
            aria-label={index === 0 ? undefined : `Character ${index + 1} of ${length}`}
            aria-labelledby={index === 0 && ariaLabel ? labelId : undefined}
            aria-describedby={index === 0 ? describedBy : undefined}
            aria-invalid={ariaInvalid || undefined}
            className={slot}
          />;
        })}
      </span>
    </span>)}
    {ariaLabel && <span id={labelId} className="sr-only">{ariaLabel}</span>}
    <span role="status" className="sr-only">{rejected}</span>
  </OTPFieldPrimitive.Root>;
}

export {OtpMode, type OtpModeProps};
